# 0 = land, 1 = water

def closedIsland(grid):
    rows = len(grid)
    cols = len(grid[0])

    def dfs(r, c):
        # If out of bounds, this land cell touches the border (not closed)
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return False
        if grid[r][c] == 1:
            return True
        # Mark visited
        grid[r][c] = 1
        closed = True
        # Visit all 4 directions
        for dr, dc in [(0,1), (1,0), (0,-1), (-1,0)]:
            if not dfs(r + dr, c + dc):
                closed = False
        return closed

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                if dfs(r, c):
                    count += 1
    return count
